"use client";

import { useState } from "react";
import { Download } from "lucide-react";
import { toast } from "sonner";
import { downloadExport, type ExportFormat, type ExportKind } from "@/lib/services";
import { Button } from "@/components/ui/button";

const LABELS: Record<ExportFormat, string> = { xlsx: "Excel", pdf: "PDF" };

/**
 * Excel / PDF buttons. The file is generated by the server from the filters passed here, never
 * from what the browser happens to display. In mock mode no file exists: a notice is shown.
 */
export function ExportButtons({
  kind,
  filters,
  formats = ["xlsx", "pdf"],
}: {
  kind: ExportKind;
  filters?: Record<string, string | undefined>;
  formats?: ExportFormat[];
}) {
  const [busy, setBusy] = useState<ExportFormat | null>(null);

  async function run(format: ExportFormat) {
    setBusy(format);
    try {
      const done = await downloadExport(kind, format, filters);
      if (!done) toast.info(`Export ${LABELS[format]} disponible avec la base de données (DATA_SOURCE=db)`);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "L'export a échoué.");
    } finally {
      setBusy(null);
    }
  }

  return (
    <>
      {formats.map((format) => (
        <Button key={format} variant="outline" disabled={busy !== null} onClick={() => run(format)}>
          <Download className="h-4 w-4" aria-hidden /> {busy === format ? "Génération…" : LABELS[format]}
        </Button>
      ))}
    </>
  );
}
